+		if matched.supersedeID != 0 {
+			if err := queries.UpdateFindingState(ctx, db.UpdateFindingStateParams{
+				State:            findingStateSuperseded,
+				MatchedFindingID: sql.NullInt64{Int64: insertedID, Valid: true},
+				ID:               matched.supersedeID,
+			}); err != nil {
+				return err
+			}
+		}
+	}
