+	for _, current := range existing {
+		if _, ok := matchedExistingIDs[current.ID]; ok {
+			continue
+		}
+		_, seenThisRun := updatedLastSeenIDs[current.ID]
+		nextState, ok, err := transitionMissingFinding(current, reviewedPaths, deletedPaths, seenThisRun)
