+		switch typed := value.(type) {
+		case string:
+			text := strings.TrimSpace(typed)
+			if text != "" {
+				return []string{text}
+			}
+		case []any:
+			items := make([]string, 0, len(typed))
+			for _, item := range typed {
+				text, ok := item.(string)
+				if !ok {
+					continue
+				}
+				text = strings.TrimSpace(text)
+				if text != "" {
